-- Australian Helper production schema (PostgreSQL 15+). Monetary values are integer cents.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email citext UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK (role IN ('poster','helper','both')), status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), refresh_token_hash text NOT NULL, device_info jsonb NOT NULL DEFAULT '{}', expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS auth_sessions_user_active_idx ON auth_sessions(user_id, expires_at) WHERE revoked_at IS NULL;
CREATE TABLE IF NOT EXISTS helpers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE NOT NULL REFERENCES users(id), bio text, service_radius_km numeric(6,2), verification_status text NOT NULL DEFAULT 'pending', stripe_account_id text, metadata jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), poster_id uuid NOT NULL REFERENCES users(id), title text NOT NULL, description text, category text, suburb text, location jsonb, budget_cents integer CHECK (budget_cents >= 0), currency char(3) NOT NULL DEFAULT 'AUD', status text NOT NULL DEFAULT 'open', accepted_offer_id uuid, scheduled_start timestamptz, scheduled_end timestamptz, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS tasks_marketplace_idx ON tasks(status, category, created_at DESC);
CREATE INDEX IF NOT EXISTS tasks_poster_idx ON tasks(poster_id, created_at DESC);
CREATE TABLE IF NOT EXISTS offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid NOT NULL REFERENCES tasks(id), helper_id uuid NOT NULL REFERENCES users(id), amount_cents integer NOT NULL CHECK (amount_cents >= 0), message text, status text NOT NULL DEFAULT 'submitted', parent_offer_id uuid REFERENCES offers(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS offers_one_active_per_helper ON offers(task_id, helper_id) WHERE status IN ('submitted','countered');
CREATE INDEX IF NOT EXISTS offers_task_idx ON offers(task_id, created_at);
CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid NOT NULL REFERENCES tasks(id), poster_id uuid NOT NULL REFERENCES users(id), helper_id uuid REFERENCES users(id), amount_cents integer NOT NULL, platform_fee_cents integer NOT NULL DEFAULT 0, stripe_payment_intent_id text UNIQUE, status text NOT NULL DEFAULT 'requires_payment', metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS stripe_webhook_events (id text PRIMARY KEY, type text NOT NULL, payload jsonb NOT NULL, processed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid REFERENCES tasks(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id), sender_id uuid NOT NULL REFERENCES users(id), body text NOT NULL, attachments jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz);
CREATE INDEX IF NOT EXISTS messages_conversation_idx ON messages(conversation_id, created_at);
CREATE TABLE IF NOT EXISTS reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid NOT NULL REFERENCES tasks(id), reviewer_id uuid NOT NULL REFERENCES users(id), reviewee_id uuid NOT NULL REFERENCES users(id), rating smallint NOT NULL CHECK (rating BETWEEN 1 AND 5), body text, status text NOT NULL DEFAULT 'published', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(task_id, reviewer_id));
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), type text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS device_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), token text UNIQUE NOT NULL, platform text NOT NULL, enabled boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action text NOT NULL, entity_type text, entity_id text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS idempotency_keys (key text PRIMARY KEY, user_id uuid REFERENCES users(id), request_hash text NOT NULL, response jsonb, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS migration_id_map (legacy_collection text NOT NULL, legacy_id text NOT NULL, new_id uuid NOT NULL, PRIMARY KEY(legacy_collection, legacy_id));
